    /// @notice Creates a new DynamicBuffer and pushes two data segments.
    function p(bytes memory data0, bytes memory data1)
        internal
        pure
        returns (DynamicBuffer memory result)
    {
        result.data = new bytes(data0.length + data1.length);
        /// @solidity memory-safe-assembly
        assembly {
            let d := add(result, 0x20)
            let p := mload(d)
            if mload(data0) {
                mstore(p, mload(data0))
                let o := 0
                for {} lt(o, mload(data0)) { o := add(o, 0x20) } {
                    mstore(add(add(p, 0x20), o), mload(add(add(data0, 0x20), o)))
