            if mload(data1) {
                let l := mload(p)
                let o := 0
                for {} lt(o, mload(data1)) { o := add(o, 0x20) } {
                    mstore(add(add(add(p, 0x20), l), o), mload(add(add(data1, 0x20), o)))
