                let n := sub(minimum, 1)
                n := or(n, shr(1, n))
                n := or(n, shr(2, n))
                n := or(n, shr(4, n))
                n := or(n, shr(8, n))
                n := or(n, shr(16, n))
                n := or(n, shr(32, n))
                n := add(n, 1)

                // Get the current data pointer and length.
                let d := mload(add(result, 0x20))
                let l := mload(d)

                // Allocate new memory.
                let p := mload(0x40)
                mstore(p, n)
                mstore(0x40, add(add(p, 0x20), n))

                // Copy the data.
                mstore(add(p, 0x20), mload(add(d, 0x20)))
